-- composition of rule kernels L:optimize_unions x P:CombinePartialFinalAggregate (datafusion), template cte_twice
WITH ka AS (SELECT ' '::text AS c0, 0.0::float8 AS c1, 'abc'::text AS c2 FROM tp AS a1 WHERE (('2000-01-01'::date BETWEEN '1970-01-01'::date AND '1970-01-01'::date) OR (EXTRACT (MICROSECONDS FROM (SELECT MIN ('2000-01-01 00:00:00+00'::timestamptz) FROM t3 AS a2)) IS NULL))), kb AS (SELECT '%'::text AS c0 INTERSECT (SELECT 'a'::text AS c0 UNION (SELECT '[1,10)'::text AS c0 UNION SELECT 'x%'::text AS c0))) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT ' '::text AS c0, 0.0::float8 AS c1, 'abc'::text AS c2 FROM tp AS a1 WHERE (('2000-01-01'::date BETWEEN '1970-01-01'::date AND '1970-01-01'::date) OR (EXTRACT (MICROSECONDS FROM (SELECT MIN ('2000-01-01 00:00:00+00'::timestamptz) FROM t3 AS a2)) IS NULL))) AS ka) + (SELECT count(*) FROM (SELECT '%'::text AS c0 INTERSECT (SELECT 'a'::text AS c0 UNION (SELECT '[1,10)'::text AS c0 UNION SELECT 'x%'::text AS c0))) AS kb)
